const result = "10" + 5;
console.log(result); // "105"

const number = Number("10");
console.log(number); // 10

console.log("10" == 10); // true

// JavaScript converts "10" to 10
// before performing the comparison.

const value = "100";

const number = Number(value);
const text = String(100);
const booleanValue = Boolean(1);

console.log(number);        // 100
console.log(text);          // "100"
console.log(booleanValue);  // true

console.log(10 == "10");  // true
console.log(10 === "10"); // false

// == converts "10" to 10
// === checks both value and type

console.log(10 != "10");   // false
console.log(10 !== "10");  // true

// 10 and "10" are considered equal by ==
// but they have different types, so === is false.

if ("Hello") {
  console.log("Truthy");
}

if (0) {
  console.log("This will not run");
}

// "Hello" is truthy
// 0 is falsy

const arr = [];

console.log(Boolean(arr)); // true

if (arr) {
  console.log("Array is truthy");
}

console.log(arr.length); // 0

const user = {};

console.log(Boolean(user)); // true

if (user) {
  console.log("Object is truthy");
}

console.log(null == undefined);  // true
console.log(null === undefined); // false

// == allows the special null/undefined comparison.
// === checks both value and type.

